fn longer<'a, 'b>(x: &'a str, y: &'b str) -> &'a str
where 'b: 'a  // y lives at least as long as x
{
    if x.len() >= y.len() { x } else { x } // returns 'a-tied value
}

// Struct holding references
struct Holder<'a> {
    data: &'a [u8],
}
```. Lifetime elision: most cases don't need explicit annotations.

